import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv3d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv3d_forward_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    const int N, const int C_in, const int D, const int H, const int W,
    const int C_out, const int K,
    const int D_out, const int H_out, const int W_out,
    const int stride, const int padding, const int dilation,
    const int groups, const int C_in_per_group, const int C_out_per_group)
{
    const long total = (long)N * C_out * D_out * H_out * W_out;
    long idx = blockIdx.x * (long)blockDim.x + threadIdx.x;
    const long stride_grid = (long)blockDim.x * gridDim.x;

    for (; idx < total; idx += stride_grid) {
        long tmp = idx;
        const int ow = tmp % W_out; tmp /= W_out;
        const int oh = tmp % H_out; tmp /= H_out;
        const int od = tmp % D_out; tmp /= D_out;
        const int oc = tmp % C_out; tmp /= C_out;
        const int n  = tmp;

        const int g = oc / C_out_per_group;
        const int ic_start = g * C_in_per_group;

        float acc = 0.0f;

        const int in_d_base = od * stride - padding;
        const int in_h_base = oh * stride - padding;
        const int in_w_base = ow * stride - padding;

        for (int icg = 0; icg < C_in_per_group; ++icg) {
            const int ic = ic_start + icg;
            const float* input_nc = input + (((long)n * C_in + ic) * D) * H * W;
            const float* weight_oc_ic = weight + (((long)oc * C_in_per_group + icg) * K) * K * K;

            for (int kd = 0; kd < K; ++kd) {
                const int id = in_d_base + kd * dilation;
                if (id < 0 || id >= D) continue;
                for (int kh = 0; kh < K; ++kh) {
                    const int ih = in_h_base + kh * dilation;
                    if (ih < 0 || ih >= H) continue;
                    const float* input_row = input_nc + ((long)id * H + ih) * W;
                    const float* weight_row = weight_oc_ic + (kd * K + kh) * K;
                    for (int kw = 0; kw < K; ++kw) {
                        const int iw = in_w_base + kw * dilation;
                        if (iw < 0 || iw >= W) continue;
                        acc += input_row[iw] * weight_row[kw];
                    }
                }
            }
        }

        output[idx] = acc;
    }
}

torch::Tensor conv3d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    int stride,
    int padding,
    int dilation,
    int groups)
{
    input = input.contiguous();
    weight = weight.contiguous();

    const int N = input.size(0);
    const int C_in = input.size(1);
    const int D = input.size(2);
    const int H = input.size(3);
    const int W = input.size(4);

    const int C_out = weight.size(0);
    const int C_in_per_group = weight.size(1);
    const int K = weight.size(2);

    const int C_out_per_group = C_out / groups;

    const int D_out = (D + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
    const int H_out = (H + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
    const int W_out = (W + 2 * padding - dilation * (K - 1) - 1) / stride + 1;

    auto output = torch::empty({N, C_out, D_out, H_out, W_out}, input.options());

    const long total = (long)N * C_out * D_out * H_out * W_out;
    const int threads = 256;
    const int blocks = (int)std::min((long)65535 * 256, (total + threads - 1) / threads);

    conv3d_forward_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C_in, D, H, W,
        C_out, K,
        D_out, H_out, W_out,
        stride, padding, dilation,
        groups, C_in_per_group, C_out_per_group
    );

    return output;
}
"""

conv3d_cpp_source = r"""
torch::Tensor conv3d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    int stride,
    int padding,
    int dilation,
    int groups);
"""

conv3d_ext = load_inline(
    name="conv3d_ext",
    cpp_sources=conv3d_cpp_source,
    cuda_sources=conv3d_source,
    functions=["conv3d_forward"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Performs a standard 3D convolution operation with square input and square kernel,
    using a custom CUDA kernel for the forward computation.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.use_bias = bias

        self.weight = nn.Parameter(torch.empty(out_channels, in_channels // groups, kernel_size, kernel_size, kernel_size))
        nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)

        if bias:
            self.bias = nn.Parameter(torch.zeros(out_channels))
        else:
            self.register_parameter('bias', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.cuda().contiguous()
        weight = self.weight.cuda().contiguous()

        out = conv3d_ext.conv3d_forward(
            x, weight,
            self.stride, self.padding, self.dilation, self.groups
        )

        if self.use_bias:
            out = out + self.bias.view(1, -1, 1, 1, 1)

        return out


batch_size = 16
in_channels = 3
out_channels = 64
kernel_size = 3
depth = 64
width = 64
height = 64


def get_inputs():
    x = torch.rand(batch_size, in_channels, depth, width, height)
    return [x]


def get_init_inputs():
    return [in_channels, out_channels, kernel_size]

